import re

TR = re.compile(r"m4trace: -(?P<depth>\d+)- (?P<macro>[^\s(]+)(?:\((?P<args>.*?)\))?(?: -> `(?P<expansion>.*)')?$")

def parse(lines):
    trace = []
    tl = []
    out = []
    ol = []
    for i, l in enumerate(lines):
        if not l.strip():
            continue
        p = l.find('m4trace: -')
        m = None
        if p >= 0 and (p == 0 or l[p - 1].isspace()):
            m = TR.match(l[p:])
        if m:
            pre = l[:p].strip()
            if pre:
                out.append({'text': pre})
                ol.append(i)
            trace.append({
                'depth': m.group('depth'),
                'macro': m.group('macro'),
                'args': m.group('args') or '',
                'expansion': m.group('expansion') or '',
            })
            tl.append(i)
        else:
            out.append({'text': l})
            ol.append(i)
    blocks = []
    if trace:
        blocks.append({'name': 'trace', 'kind': 'table', 'lines': tl, 'records': trace})
    if out:
        blocks.append({'name': 'output', 'kind': 'table', 'lines': ol, 'records': out})
    return {'blocks': blocks, 'skip': []}
